/**
 * خطّا اللوحة — **مضمَّنان لا مطلوبان من شبكة** (D-089).
 *
 * ## لا يُحرَّر بيد
 *
 * وُلّد بـ `node scripts/embed_ui_font.mjs` من حزمتَي
 * `@fontsource-variable` المثبَّتتين بنسختيهما في `package.json`.
 * **وأيُّ تعديلٍ هنا يُمحى عند إعادة التوليد.**
 *
 * ## ولماذا الضمّ
 *
 * ثلاثُ رحلاتٍ إلى `fonts.googleapis.com` قبل رسم الحرف الأوّل، وثمنٌ
 * ثالثٌ ليس أداءً: **كلُّ فتحةٍ للوحة تقول لطرفٍ ثالثٍ متى فتحها المالك.**
 *
 * ## والمتغيّرُ لا الثابت
 *
 * ملفٌّ واحدٌ لكلّ أسرةٍ يغطّي ‏٤٠٠ إلى ‏٧٠٠ — أقلُّ بايتا من ثلاثة أوجهٍ
 * ثابتة، **ويعطي الوزنَ ‏٥٠٠** الذي كان سيُقرَّب.
 *
 * ## الرخصة
 *
 * Beiruti و Inter — SIL Open Font License 1.1، وهي تجيز الضمَّ وإعادةَ
 * التوزيع داخل برنامج. حقوقُ المؤلّفين محفوظةٌ لأصحابها.
 */

/** وجهُ خطٍّ مضمَّن: بصمتُه في مساره، وبايتاتُه `base64`. */
export interface EmbeddedFace {
  readonly family: string
  readonly hash: string
  readonly path: string
  readonly bytes: number
  readonly b64: string
}

/** العربيّةُ — وهي المتنُ كلُّه · 55.8KB · beiruti-arabic-wght-normal.woff2 */
export const BEIRUTI: EmbeddedFace = {
  family: 'Beiruti',
  hash: '39b09ced',
  path: '/f/beiruti.39b09ced.woff2',
  bytes: 57144,
  b64: '',
}

/** اللاتينيُّ والرقم — أسماءُ النماذج والمعرّفاتُ والمبالغ · 47.1KB · inter-latin-wght-normal.woff2 */
export const INTER: EmbeddedFace = {
  family: 'Inter',
  hash: '3100e775',
  path: '/f/inter.3100e775.woff2',
  bytes: 48256,
  b64: '',
}

/** الوجهان معا — يُمسحان في المسار وفي القشرة، فلا يُنسى أحدُهما. */
export const FACES: readonly EmbeddedFace[] = [BEIRUTI, INTER]
